addQ("pan-k4-u10", 4, "Analisis Bentuk Negara Indonesia", "sulit", "Berdasarkan Pasal 1 ayat (1) UUD 1945, negara Indonesia adalah negara kesatuan yang berbentuk Republik. Hal ini menegaskan bahwa kedaulatan tertinggi berada di tangan ...", ["Rakyat dan dilaksanakan menurut Undang-Undang Dasar", "Raja secara turun temurun", "Segelintir orang kaya pemilik modal", "Aparat militer semata"], 0, "Bentuk republik menegaskan kedaulatan rakyat melalui konstitusi hukum (demokrasi).");
