addQ("pan-k4-u17", 4, "Sikap Menghargai Ritual Kasada di Bromo", "sulit", "Masyarakat suku Tengger di Gunung Bromo mengadakan upacara Yadnya Kasada dengan melempar hasil bumi ke kawah bromo. Makna luhur dari ritual adat ini adalah ...", ["Ungkapan rasa syukur kepada Sang Hyang Widhi dan menghormati leluhur Roro Anteng dan Joko Seger", "Membuang makanan yang tidak enak", "Mengotori kawasan wisata kawah", "Menakut-nakuti para wisatawan asing"], 0, "Yadnya Kasada merupakan wujud religiusitas dan penghormatan adat leluhur suku Tengger.");
addQ("pan-k4-u18", 4, "Dampak Tidak Dilaksanakannya Kewajiban Ronda Malam", "sulit", "Jika warga komplek perumahan enggan menjalankan kewajiban ronda malam (siskamling), risiko yang akan timbul bagi lingkungan adalah ...", ["Tingkat kerawanan kejahatan pencurian meningkat dan lingkungan menjadi tidak aman", "Harga tanah perumahan melambung tinggi", "Warga menjadi lebih sehat karena banyak tidur", "Pos ronda bertambah mewah"], 0, "Siskamling menjaga ketertiban, keamanan, dan kewaspadaan lingkungan komunal.");
addQ("pan-k4-u19", 4, "Penerapan Keadilan Distributif di Sekolah", "sulit", "Pemberian beasiswa Program Indonesia Pintar (PIP) diprioritaskan bagi murid dari keluarga yang kurang mampu secara ekonomi. Kebijakan ini merupakan wujud keadilan yang bertujuan untuk ...", ["Membantu pemerataan akses pendidikan bagi anak-anak yang membutuhkan", "Membeda-bedakan kasta status sosial murid", "Memanjakan murid yang malas belajar", "Menghukum murid dari keluarga mampu"], 0, "Pemerataan akses pendidikan adalah amanat keadilan sosial bagi seluruh rakyat.");
addQ("pan-k4-u20", 4, "Makna Padi dan Kapas Hubungannya dengan Kesejahteraan", "sulit", "Mengapa lambang keadilan sosial menggunakan padi dan kapas, bukan emas dan intan permata?", ["Karena kebutuhan pokok pangan dan sandang adalah hak paling mendasar seluruh rakyat tanpa terkecuali", "Karena emas terlalu berat digambar pada perisai", "Karena intan hanya ada di luar negeri", "Karena padi dan kapas harganya sangat murah"], 0, "Kesejahteraan sosial diukur dari terpenuhinya kebutuhan pokok hidup rakyat (pangan dan sandang).");
addQ("pan-k4-u21", 4, "Tanggung Jawab Pemimpin Upacara", "sulit", "Seorang pemimpin upacara bendera harus bersuara lantang, bersikap tegap, dan disiplin dalam memimpin barisan. Tanggung jawab ini menuntut karakter ...", ["Kepemimpinan yang tegas, berwibawa, dan bertanggung jawab", "Sikap sombong memamerkan seragam baru", "Keinginan menguasai seluruh lapangan", "Suka memerintah teman semaunya"], 0, "Keteladanan pemimpin upacara memancarkan disiplin dan rasa hormat kebangsaan.");
addQ("pan-k4-u22", 4, "Nilai Kejujuran dalam Pengelolaan Kas Kelas", "sulit", "Bendahara kelas mencatat keluar masuk uang kas kelas secara terbuka di papan pengumuman agar dapat dilihat oleh seluruh siswa. Tindakan bendahara ini menerapkan prinsip ...", ["Transparansi, kejujuran, dan akuntabilitas moral", "Pamer kekayaan uang kas", "Pemborosan waktu belajar", "Mencari pujian dari kepala sekolah"], 0, "Keterbukaan informasi keuangan mencegah kecurigaan dan melatih tata kelola yang jujur.");
addQ("pan-k4-u23", 4, "Konsekuensi Peredaran Berita Hoaks Pemilu", "sulit", "Penyebaran informasi bohong dan ujaran kebencian di masa pemilihan kepala daerah dapat merusak tatanan bangsa karena memicu ...", ["Perpecahan sosial, konflik horizontal antarpendukung, dan rusaknya persatuan", "Kemajuan ekonomi daerah yang pesat", "Kecerdasan literasi masyarakat bertambah", "Kedamaian hidup bertetangga"], 0, "Hoaks dan ujaran kebencian membelah kohesi sosial dan memicu anarki.");
addQ("pan-k4-u24", 4, "Kearifan Budaya Pelestarian Terumbu Karang", "sulit", "Nelayan tradisional di Raja Ampat menggunakan alat pancing ramah lingkungan dan melarang penggunaan bom ikan atau racun potasium. Kepatuhan nelayan ini dilandasi oleh kesadaran ...", ["Melindungi ekosistem laut dan keberlangsungan sumber daya hayati bagi generasi anak cucu", "Ketakutan pada penjaga pantai saja", "Karena harga racun potasium mahal", "Supaya ikan tidak mau memakan umpan"], 0, "Menjaga kelestarian bahari menjamin ketahanan pangan dan kelestarian hayati laut nusantara.");
addQ("pan-k4-u25", 4, "Tenggang Rasa Terhadap Tetangga yang Sedang Sakit", "sulit", "Tetangga sebelah rumah kita sedang menderita sakit parah dan membutuhkan istirahat tenang di kamarnya. Tindakan kita yang paling santun dan mencerminkan adab bertetangga adalah ...", ["Menurunkan volume suara televisi dan tidak membunyikan klakson keras di depan rumahnya", "Mengadakan latihan musik drum band di teras depan", "Mengundang teman-teman berpesta larut malam", "Menyalakan mesin gergaji mesin tanpa henti"], 0, "Tenggang rasa menjaga ketenangan orang sakit wujud kepedulian sosial.");
addQ("pan-k4-u26", 4, "Analisis Nilai Sila Ke-1 dalam Kehidupan Modern", "sulit", "Di era digital yang penuh keterbukaan informasi, nilai Ketuhanan Yang Maha Esa berfungsi sebagai ...", ["Benteng moral dan kendali diri dari pengaruh konten negatif dan kemaksiatan", "Penghalang untuk kemajuan teknologi", "Alasan untuk menutup diri dari dunia luar", "Alat untuk membenci budaya lain"], 0, "Keimanan kepada Tuhan menjadi filter etis dari bahaya arus informasi negatif.");
addQ("pan-k4-u27", 4, "Penyelesaian Sengketa Tanah Ulayat Adat", "sulit", "Sengketa tapal batas tanah adat antara dua marga sebaiknya diselesaikan melalui jalur peradilan adat yang mengedepankan ...", ["Musyawarah para tetua adat dengan mengutamakan perdamaian dan keadilan", "Peperangan antarsuku menggunakan senjata tajam", "Pembakaran rumah penduduk yang berselisih", "Siapa yang paling kuat berhak merebut tanah"], 0, "Musyawarah tetua adat mengembalikan keseimbangan dan perdamaian persaudaraan.");
addQ("pan-k4-u28", 4, "Hak Suara dalam Pengambilan Keputusan Kelas", "sulit", "Dalam pemilihan program kerja kelas 4, setiap siswa memiliki hak 1 suara yang sama nilainya, baik murid kaya, kurang mampu, laki-laki, maupun perempuan. Hal ini menunjukkan prinsip ...", ["Persamaan derajat dan kesetaraan hak dalam berdemokrasi", "Ketidakadilan terhadap siswa pintar", "Keuntungan bagi ketua kelas", "Pemungutan suara yang tidak berguna"], 0, "Demokrasi Pancasila menjunjung kesetaraan martabat setiap individu (one person one vote).");
addQ("pan-k4-u29", 4, "Kewajiban Menjaga Satwa Langka Indonesia", "sulit", "Pemerintah melarang perburuan liar terhadap hewan endemik seperti Orangutan, Komodo, dan Harimau Sumatera. Alasan utama perlindungan satwa langka ini adalah ...", ["Mencegah kepunahan satwa dan menjaga keseimbangan rantai makanan ekosistem alam", "Agar satwa tersebut bisa dijual mahal ke luar negeri", "Untuk disembelih sebagai makanan pesta", "Supaya hutan menjadi sepi"], 0, "Satwa langka adalah pusaka keanekaragaman hayati nusantara yang tidak ternilai harganya.");
addQ("pan-k4-u30", 4, "Peran Generasi Muda Menjaga Keutuhan NKRI", "sulit", "Tantangan terbesar generasi muda Indonesia dalam mempertahankan NKRI di era globalisasi adalah ...", ["Menyaring budaya asing yang merusak moral dan memperkokoh jati diri kebangsaan berdasarkan Pancasila", "Meniru segala macam gaya hidup bebas barat", "Meninggalkan bahasa Indonesia dan budaya daerah", "Memusuhi seluruh negara asing tanpa alasan"], 0, "Ketahanan budaya dan penguatan moral Pancasila membentengi bangsa dari distorsi nilai.");

