addQ("pan-k5-m01", 5, "Konstitusi Negara Indonesia", "mudah", "Hukum dasar tertulis yang menjadi sumber hukum tertinggi di negara Republik Indonesia adalah ...", ["Undang-Undang Dasar Negara Republik Indonesia Tahun 1945", "Peraturan Pemerintah", "Peraturan Daerah", "Surat Keputusan Camat"], 0, "UUD NRI 1945 adalah hukum dasar tertinggi tertulis negara.");
addQ("pan-k5-m02", 5, "Jumlah Bab UUD 1945", "mudah", "Undang-Undang Dasar 1945 hasil amandemen terdiri atas Pembukaan dan pasal-pasal. Pembukaan UUD 1945 terdiri dari ... alinea.", ["4 alinea", "5 alinea", "3 alinea", "6 alinea"], 0, "Pembukaan UUD NRI 1945 terdiri dari 4 alinea.");
addQ("pan-k5-m03", 5, "Tujuan Negara di Pembukaan UUD 1945", "mudah", "Tujuan nasional bangsa Indonesia tercantum dalam Pembukaan UUD 1945 alinea ke- ...", ["Empat", "Satu", "Dua", "Tiga"], 0, "Alinea ke-4 memuat 4 tujuan negara dan dasar negara Pancasila.");
addQ("pan-k5-m04", 5, "Bentuk Pemerintahan NKRI", "mudah", "Bentuk pemerintahan negara Indonesia adalah ...", ["Republik", "Monarki (Kerajaan)", "Kekaisaran", "Keamiran"], 0, "Pasal 1 ayat 1 menegaskan bentuk pemerintahan Indonesia adalah Republik.");
addQ("pan-k5-m05", 5, "Kepala Negara dan Pemerintahan", "mudah", "Dalam sistem pemerintahan presidensial di Indonesia, yang bertindak sebagai kepala negara sekaligus kepala pemerintahan adalah ...", ["Presiden", "Perdana Menteri", "Ketua DPR", "Ketua MPR"], 0, "Presiden Republik Indonesia memegang kekuasaan pemerintahan sebagai kepala negara dan kepala pemerintahan.");
addQ("pan-k5-m06", 5, "Lembaga Pembuat Undang-Undang", "mudah", "Lembaga legislatif yang memiliki wewenang membuat undang-undang bersama Presiden adalah ...", ["Dewan Perwakilan Rakyat (DPR)", "Mahkamah Agung", "Badan Pemeriksa Keuangan", "Komisi Pemberantasan Korupsi"], 0, "DPR memegang kekuasaan membentuk Undang-Undang (fungsi legislasi).");
addQ("pan-k5-m07", 5, "Masa Jabatan Presiden", "mudah", "Masa jabatan Presiden dan Wakil Presiden Republik Indonesia dalam satu periode adalah selama ... tahun.", ["5 tahun", "4 tahun", "6 tahun", "10 tahun"], 0, "Presiden dan Wapres memegang jabatan selama 5 tahun dan dapat dipilih kembali satu kali masa jabatan.");
addQ("pan-k5-m08", 5, "Hak Asasi Manusia (HAM)", "mudah", "Hak kodrati yang melekat pada diri manusia sejak lahir sebagai anugerah Tuhan Yang Maha Esa dinamakan ...", ["Hak Asasi Manusia (HAM)", "Hak waris", "Hak cipta dagang", "Hak istimewa pejabat"], 0, "HAM adalah anugerah Tuhan yang wajib dihormati dan dilindungi oleh negara.");
addQ("pan-k5-m09", 5, "Kewajiban Bela Negara Pasal UUD", "mudah", "Kewajiban setiap warga negara untuk ikut serta dalam upaya pembelaan negara tercantum dalam UUD 1945 Pasal ...", ["Pasal 27 ayat (3)", "Pasal 33 ayat (1)", "Pasal 29 ayat (1)", "Pasal 36"], 0, "Pasal 27 ayat (3) mengatur hak dan kewajiban tiap warga negara dalam pembelaan negara.");
addQ("pan-k5-m10", 5, "Kewajiban Pendidikan Dasar", "mudah", "Pasal 31 ayat (2) UUD 1945 menegaskan bahwa setiap warga negara wajib mengikuti pendidikan dasar dan pemerintah wajib ...", ["Membiayainya", "Menutup sekolahnya", "Memungut biaya mahal", "Menghapuskannya"], 0, "Pemerintah wajib membiayai pendidikan dasar bagi seluruh warga negara.");

addQ("pan-k5-s01", 5, "Empat Tujuan Negara di Pembukaan UUD 1945", "sedang", "Berikut ini yang BUKAN merupakan salah satu dari empat tujuan negara Indonesia dalam Pembukaan UUD 1945 alinea IV adalah ...", ["Menguasai dan menjajah wilayah negara lain", "Melindungi segenap bangsa Indonesia dan seluruh tumpah darah Indonesia", "Memajukan kesejahteraan umum", "Mencerdaskan kehidupan bangsa"], 0, "Indonesia anti penjajahan dan tidak berniat menjajah wilayah bangsa lain.");
addQ("pan-k5-s02", 5, "Sistem Pertahanan Keamanan Rakyat Semesta", "sedang", "Sistem pertahanan dan keamanan negara Indonesia yang melibatkan seluruh rakyat dengan TNI dan POLRI sebagai kekuatan utama dinamakan ...", ["Sishankamrata (Sistem Pertahanan Keamanan Rakyat Semesta)", "Sistem tentara bayaran", "Sistem militer tertutup", "Pakta pertahanan barat"], 0, "Sishankamrata memposisikan TNI/Polri sebagai kekuatan utama dan rakyat sebagai kekuatan pendukung.");
addQ("pan-k5-s03", 5, "Hak Memperoleh Pekerjaan dan Penghidupan Layak", "sedang", "Tiap-tiap warga negara berhak atas pekerjaan dan penghidupan yang layak bagi kemanusiaan. Hal ini dijamin dalam UUD 1945 Pasal ...", ["Pasal 27 ayat (2)", "Pasal 34 ayat (1)", "Pasal 30 ayat (2)", "Pasal 31 ayat (3)"], 0, "Pasal 27 ayat (2) menjamin hak atas pekerjaan dan penghidupan layak.");
addQ("pan-k5-s04", 5, "Fakir Miskin dan Anak Telantar", "sedang", "Pasal 34 ayat (1) UUD NRI 1945 menyatakan bahwa fakir miskin dan anak-anak telantar dipelihara oleh ...", ["Negara", "Lembaga asing", "Yayasan swasta saja", "Dibiarkan mandiri"], 0, "Konstitusi mewajibkan negara menjamin pemeliharaan fakir miskin dan anak telantar.");
addQ("pan-k5-s05", 5, "Perekonomian Berdasarkan Asas Kekeluargaan", "sedang", "Pasal 33 ayat (1) UUD 1945 menyatakan perekonomian disusun sebagai usaha bersama berdasar atas asas kekeluargaan. Badan usaha yang paling cocok dengan pasal ini adalah ...", ["Koperasi", "Perusahaan asing swasta", "Konglomerasi perseorangan", "Firma rentenir"], 0, "Koperasi beroperasi berlandaskan asas kekeluargaan demi kemakmuran bersama.");
addQ("pan-k5-s06", 5, "Kekayaan Alam Dikuasai Negara", "sedang", "Bumi, air, dan kekayaan alam yang terkandung di dalamnya dikuasai oleh negara dan dipergunakan untuk sebesar-besar ...", ["Kemakmuran rakyat", "Keuntungan presiden", "Kekayaan para menteri", "Kas perusahaan tambang"], 0, "Kekayaan alam diperuntukkan bagi sebesar-besar kemakmuran seluruh rakyat Indonesia.");
addQ("pan-k5-s07", 5, "Peran Mahkamah Agung (MA)", "sedang", "Lembaga yudikatif yang memegang kekuasaan kehakiman tertinggi untuk mengadili perkara pada tingkat kasasi adalah ...", ["Mahkamah Agung (MA)", "Dewan Perwakilan Daerah (DPD)", "Komisi Yudisial (KY)", "Presiden"], 0, "Mahkamah Agung membawahi peradilan umum, agama, militer, dan tata usaha negara.");
addQ("pan-k5-s08", 5, "Peran Mahkamah Konstitusi (MK)", "sedang", "Lembaga kehakiman yang berwenang menguji undang-undang terhadap UUD 1945 dan memutus sengketa hasil pemilihan umum adalah ...", ["Mahkamah Konstitusi (MK)", "Mahkamah Agung", "Kejaksaan Negeri", "Badan Pengawas Pemilu"], 0, "MK menguji kesesuaian undang-undang terhadap UUD 1945.");
addQ("pan-k5-s09", 5, "Peran Badan Pemeriksa Keuangan (BPK)", "sedang", "Lembaga negara yang bertugas memeriksa pengelolaan dan tanggung jawab keuangan negara secara bebas dan mandiri adalah ...", ["Badan Pemeriksa Keuangan (BPK)", "Bank Indonesia", "Kementerian Keuangan", "DPRD"], 0, "BPK memeriksa akuntabilitas penggunaan uang negara.");
addQ("pan-k5-s10", 5, "Komisi Pemilihan Umum (KPU)", "sedang", "Lembaga independen yang bertugas menyelenggarakan pemilihan umum anggota DPR, DPD, Presiden, dan DPRD secara berkala di Indonesia adalah ...", ["Komisi Pemilihan Umum (KPU)", "Bawaslu", "KPK", "Komnas HAM"], 0, "KPU adalah penyelenggara pemilu di tingkat nasional hingga daerah.");
addQ("pan-k5-s11", 5, "Asas Pemilu Luber Jurdil", "sedang", "Asas pemilu di Indonesia adalah LUBER dan JURDIL. Kepanjangan dari LUBER adalah ...", ["Langsung, Umum, Bebas, Rahasia", "Lancar, Unggul, Bersih, Rapi", "Lugas, Unik, Berani, Rukun", "Lega, Usaha, Bekerja, Rajin"], 0, "LUBER adalah singkatan Langsung, Umum, Bebas, dan Rahasia.");
addQ("pan-k5-s12", 5, "Asas Jurdil Pemilu", "sedang", "Kepanjangan dari JURDIL dalam asas pelaksanaan pemilu Indonesia adalah ...", ["Jujur dan Adil", "Jelas dan Nyata", "Jenaka dan Rukun", "Jeli dan Teliti"], 0, "JURDIL bermakna Jujur dan Adil bagi seluruh pihak yang terlibat pemilu.");
addQ("pan-k5-s13", 5, "Penerapan Sila Ketuhanan di Era Digital", "sedang", "Salah satu wujud pengamalan sila pertama Pancasila saat bermedia sosial di internet adalah ...", ["Menyebarkan pesan damai, kebaikan, dan tidak mencela agama lain", "Menyebarkan video penistaan agama", "Membuat status provokatif yang menyinggung keyakinan warga", "Mengajak orang membenci rumah ibadah"], 0, "Etika digital berlandaskan keimanan mencerminkan kematangan beragama.");
addQ("pan-k5-s14", 5, "Penerapan Sila Kemanusiaan Melawan Perundungan Siber", "sedang", "Cyberbullying atau perundungan di media sosial yang menghina fisik atau mencemarkan nama baik orang lain melanggar nilai Pancasila sila ke- ...", ["Dua (Kemanusiaan yang adil dan beradab)", "Satu", "Tiga", "Empat"], 0, "Cyberbullying merusak kesehatan mental korban dan melanggar adab kemanusiaan.");
addQ("pan-k5-s15", 5, "Pelestarian Warisan Budaya Batik", "sedang", "Batik Indonesia telah ditetapkan oleh UNESCO sebagai Warisan Kemanusiaan untuk Budaya Lisan dan Nonbendawi. Kebanggaan ini mengamalkan sila ke- ...", ["Tiga (Persatuan Indonesia)", "Satu", "Empat", "Dua"], 0, "Batik memperkokoh identitas nasional dan rasa persatuan bangsa.");
addQ("pan-k5-s16", 5, "Tradisi Barapen / Bakar Batu di Papua", "sedang", "Upacara Bakar Batu di Papua merupakan ritual memasak bersama seluruh warga satu lembah untuk merayakan perdamaian atau panen raya. Tradisi ini menanamkan nilai ...", ["Kerukunan, persaudaraan, dan solidaritas komunal", "Persaingan antarsuku", "Pemborosan kayu bakar", "Pamer kekuatan fisik"], 0, "Bakar batu mengikat tali persaudaraan dan merawat rekonsiliasi perdamaian.");
addQ("pan-k5-s17", 5, "Tradisi Tedak Siten di Jawa", "sedang", "Tradisi upacara adat 'Tedak Siten' di Jawa diselenggarakan saat seorang bayi berusia tujuh lapan (sekitar 7 bulan) untuk melambangkan ...", ["Doa restu agar anak tumbuh mandiri, sukses, dan berbakti kepada orang tua serta tanah air", "Menghitung harta kekayaan orang tua", "Pesta ulang tahun mewah", "Pemberian gelar bangsawan"], 0, "Tedak siten sarat filosofi doa kesiapan anak menapaki langkah kehidupan di bumi.");
addQ("pan-k5-s18", 5, "Pentingnya Menjaga Bahasa Daerah dari Kepunahan", "sedang", "Banyak bahasa daerah di Indonesia yang terancam punah karena generasi mudanya enggan menuturkannya. Upaya nyata generasi muda untuk melestarikannya adalah ...", ["Mempelajari, bangga, dan aktif bertutur bahasa daerah di lingkungan keluarga serta komunitas", "Melarang bahasa daerah diajarkan di sekolah", "Menganggap bahasa daerah kampungan", "Hanya mau berbicara bahasa asing"], 0, "Menuturkan bahasa daerah menjaga warisan kekayaan kearifan nusantara.");
addQ("pan-k5-s19", 5, "Tanggung Jawab Menjaga Kebersihan Sungai Brantas/Citarum", "sedang", "Gerakan pembersihan daerah aliran sungai nasional dari limbah pabrik dan sampah plastik mencerminkan tanggung jawab warga negara dalam mewujudkan ...", ["Kelestarian lingkungan hidup yang sehat dan aman dari bahaya banjir", "Keuntungan bagi para pemulung semata", "Hiasan tepi sungai", "Tempat pembuangan limbah baru"], 0, "Menjaga DAS adalah tanggung jawab ekologis lintas generasi.");
addQ("pan-k5-s20", 5, "Sikap Menghargai Keputusan Hakim Pengadilan", "sedang", "Sebagai negara hukum (rechtsstaat), ketika hakim pengadilan telah menjatuhkan putusan hukum yang berkekuatan tetap, sikap seluruh warga negara hendaknya ...", ["Menghormati dan mematuhi keputusan hukum tersebut", "Membakar gedung pengadilan", "Mengerahkan massa untuk merusak fasilitas umum", "Menghakimi hakim secara anarkis"], 0, "Kepatuhan pada hukum menegakkan supremasi hukum dan ketertiban negara.");

addQ("pan-k5-u01", 5, "Analisis Makna Indonesia sebagai Negara Hukum", "sulit", "Pasal 1 ayat (3) UUD 1945 menegaskan: 'Negara Indonesia adalah negara hukum.' Konsekuensi hukum dari asas ini adalah ...", ["Segala tindakan penyelenggara negara dan warga negara harus berlandaskan pada hukum yang berlaku dan terdapat persamaan derajat di hadapan hukum (equality before the law)", "Hukum hanya berlaku bagi rakyat kecil yang tidak punya uang", "Pejabat kebal dari segala macam aturan hukum", "Presiden boleh membuat aturan sendiri tanpa persetujuan DPR"], 0, "Prinsip rechtsstaat menjamin tidak ada kekuasaan sewenang-wenang dan semua orang sama di mata hukum.");
addQ("pan-k5-u02", 5, "Analisis Keterkaitan Alinea I dan Pembelaan Palestina", "sulit", "Alinea pertama Pembukaan UUD 1945 berbunyi: 'Bahwa sesungguhnya kemerdekaan itu ialah hak segala bangsa dan oleh sebab itu, maka penjajahan di atas dunia harus dihapuskan karena tidak sesuai dengan perikemanusiaan dan perikeadilan.' Sikap diplomasi luar negeri Indonesia yang konsisten membela kemerdekaan bangsa Palestina berlandaskan pada ...", ["Komitmen moral konstitusi menentang segala bentuk kolonialisme dan penindasan di dunia", "Keinginan menguasai wilayah Timur Tengah", "Mencari keuntungan perdagangan senjata", "Paksaan dari negara tetangga"], 0, "Alinea I menjadi kompas politik luar negeri Indonesia yang bebas aktif anti kolonialisme.");
addQ("pan-k5-u03", 5, "Analisis Keterkaitan Pokok Pikiran Pembukaan UUD 1945", "sulit", "Pokok pikiran pertama Pembukaan UUD 1945 menegaskan bahwa negara melindungi segenap bangsa Indonesia dan seluruh tumpah darah Indonesia dengan berdasar atas persatuan. Pokok pikiran ini merupakan penjabaran langsung dari sila Pancasila ke- ...", ["Tiga (Persatuan Indonesia)", "Satu", "Dua", "Lima"], 0, "Pokok pikiran persatuan merupakan manifestasi sila ke-3 Pancasila.");
addQ("pan-k5-u04", 5, "Analisis Pokok Pikiran Keadilan Sosial", "sulit", "Pokok pikiran kedua Pembukaan UUD 1945 menyatakan bahwa negara hendak mewujudkan keadilan sosial bagi seluruh rakyat Indonesia. Kebijakan pemerintah yang paling mencerminkan pokok pikiran ini adalah ...", ["Pembangunan jalan tol lintas daerah terpencil dan subsidi BBM satu harga hingga pulau terluar", "Pembangunan gedung mewah khusus pejabat di ibu kota", "Penarikan pajak tinggi hanya kepada petani miskin", "Pemberian hak istimewa kepada pengusaha monopoli"], 0, "Keadilan sosial diwujudkan melalui pemerataan pembangunan infrastruktur dan harga kebutuhan.");
addQ("pan-k5-u05", 5, "Analisis Pokok Pikiran Kedaulatan Rakyat", "sulit", "Pokok pikiran ketiga Pembukaan UUD 1945 menyatakan bahwa negara berkedaulatan rakyat berdasar atas kerakyatan dan permusyawaratan/perwakilan. Lembaga negara yang merupakan representasi langsung seluruh rakyat pemilih di Indonesia adalah ...", ["Dewan Perwakilan Rakyat (DPR)", "Mahkamah Konstitusi", "Komisi Yudisial", "Badan Pemeriksa Keuangan"], 0, "DPR dipilih langsung oleh rakyat melalui pemilu sebagai wakil rakyat di parlemen.");
addQ("pan-k5-u06", 5, "Analisis Pokok Pikiran Ketuhanan dan Kemanusiaan", "sulit", "Pokok pikiran keempat Pembukaan UUD 1945 mewajibkan pemerintah dan penyelenggara negara untuk memelihara budi pekerti kemanusiaan yang luhur dan memegang teguh cita-cita moral rakyat yang luhur. Hal ini mewajibkan para pemimpin bangsa untuk ...", ["Menjalankan amanah kekuasaan dengan jujur, berintegritas, anti-korupsi, dan takut kepada Tuhan", "Mementingkan kekayaan pribadi dan keluarganya", "Menghalalkan segala cara demi mempertahankan jabatan", "Membuat undang-undang yang menindas kaum lemah"], 0, "Pokok pikiran ke-4 mewajibkan kepemimpinan berlandaskan akhlak mulia dan ketakwaan.");
addQ("pan-k5-u07", 5, "Analisis Bentuk Otonomi Daerah di Indonesia", "sulit", "Pemerintah Indonesia menerapkan prinsip otonomi daerah yang luas, nyata, dan bertanggung jawab. Tujuan utama pemberian otonomi daerah kepada pemerintah kabupaten dan kota adalah ...", ["Meningkatkan pelayanan publik, mempercepat pembangunan daerah, dan memberdayakan potensi lokal", "Memisahkan diri dari Negara Kesatuan Republik Indonesia", "Membentuk kerajaan kecil yang bebas dari kontrol pusat", "Membagi-bagi kekuasaan untuk keluarga bupati"], 0, "Otonomi daerah bertujuan mendekatkan pelayanan birokrasi dan memaksimalkan potensi daerah.");
addQ("pan-k5-u08", 5, "Sikap Menghadapi Paham Radikalisme dan Intoleransi", "sulit", "Gerakan radikalisme yang memaksakan kehendak dan menolak Pancasila serta semboyan Bhinneka Tunggal Ika sangat berbahaya bagi keutuhan bangsa karena dapat menimbulkan ...", ["Disintegrasi bangsa, perang saudara antarsesama anak bangsa, dan runtuhnya NKRI", "Kemajuan pesat teknologi bangsa", "Kerukunan hidup yang abadi", "Peningkatan ekonomi rakyat"], 0, "Paham intoleran dan radikal merusak pilar persatuan dan memicu perpecahan bangsa.");
addQ("pan-k5-u09", 5, "Analisis Sumpah Pemuda Sebagai Tonggak Integrasi", "sulit", "Para pemuda pada tahun 1928 menyadari bahwa perjuangan kemerdekaan sebelum abad ke-20 selalu mengalami kegagalan (seperti Perang Diponegoro, Perang Padri, Perang Pattimura). Penyebab utama kegagalan perjuangan masa lalu tersebut adalah ...", ["Perjuangan masih bersifat kedaerahan (parsial), belum bersatu, dan mudah diadu domba politik devide et impera Belanda", "Ketiadaan pemimpin yang gagah berani", "Kurangnya pasokan rempah-rempah", "Rakyat tidak mau ikut berperang"], 0, "Sifat kedaerahan memudahkan penjajah Belanda memecah belah kekuatan rakyat nusantara.");
addQ("pan-k5-u10", 5, "Penerapan Restorative Justice dalam Hukum Adat", "sulit", "Di berbagai daerah adat Indonesia, penyelesaian perselisihan kecil antarwarga sering diselesaikan melalui musyawarah damai adat untuk memulihkan keharmonisan warga tanpa harus langsung membawa ke penjara. Pendekatan keadilan ini dinamakan ...", ["Keadilan Restoratif (Restorative Justice)", "Keadilan Diktator", "Hukum Rimba", "Keadilan Sepihak"], 0, "Restorative justice menekankan pemulihan hubungan sosial dan perdamaian komunal.");
addQ("pan-k5-u11", 5, "Dilema Perlindungan Konsumen dan Tanggung Jawab Produsen", "sulit", "Sebuah produsen makanan ringan kedapatan menggunakan bahan pewarna tekstil berbahaya yang dilarang undang-undang demi menekan biaya produksi. Tindakan produsen ini merupakan pelanggaran berat karena ...", ["Membahayakan keselamatan dan kesehatan jiwa konsumen demi keuntungan finansial sepihak", "Membuat kemasan makanan menjadi terlalu menarik", "Membantu anak-anak menghemat uang saku", "Mengurangi sampah plastik"], 0, "Melanggar UU Perlindungan Konsumen dan mengancam keselamatan generasi penerus.");
addQ("pan-k5-u12", 5, "Analisis Kedaulatan Wilayah Udara Indonesia", "sulit", "Pesawat militer asing melintasi ruang udara wilayah kedaulatan Indonesia tanpa izin diplomatik resmi. Tindakan tegas yang wajib dilakukan oleh TNI Angkatan Udara sesuai hukum internasional adalah ...", ["Melakukan pencegatan (intercept), memaksa pesawat mendarat di pangkalan militer RI, dan memproses hukum pelanggaran wilayah", "Membiarkannya terbang bebas karena takut konflik", "Mengajak pesawat tersebut berfoto bersama", "Memberikan izin bahan bakar gratis"], 0, "Penegakan kedaulatan ruang udara adalah mandat pertahanan wilayah yurisdiksi nasional.");
addQ("pan-k5-u13", 5, "Analisis Makna Pasal 30 ayat (1) UUD 1945", "sulit", "Pasal 30 ayat (1) UUD 1945 menyatakan: 'Tiap-tiap warga negara berhak dan wajib ikut serta dalam usaha pertahanan dan keamanan negara.' Hal ini menegaskan bahwa pembelaan negara bukan hanya tugas militer TNI melainkan ...", ["Hak dan kewajiban moral seluruh rakyat Indonesia sesuai profesi dan keahliannya masing-masing", "Tugas polisi lalu lintas saja", "Tanggung jawab kementerian luar negeri semata", "Hanya tugas relawan bencana"], 0, "Pertahanan semesta melibatkan partisipasi aktif seluruh komponen bangsa.");
addQ("pan-k5-u14", 5, "Kearifan Konservasi Hutan Adat Larangan di Riau", "sulit", "Masyarakat adat Kenagarian Rumbio di Riau memiliki 'Hutan Adat Larangan' yang dijaga ketat, di mana siapa pun yang menebang satu pohon tanpa izin adat dikenai denda semen dan hewan ternak. Kearifan lokal ini berhasil membuktikan bahwa ...", ["Hukum adat sangat efektif menjaga kelestarian hutan dan mencegah pemanasan global", "Hukum adat merugikan para pengusaha kayu", "Masyarakat adat menolak kemajuan modern", "Hutan larangan angker dan penuh hantu"], 0, "Hukum adat terbukti ampuh melestarikan ekosistem hutan hujan tropis nusantara.");
addQ("pan-k5-u15", 5, "Bahaya Sikap Konsumerisme Terhadap Nilai Pancasila", "sulit", "Perilaku hidup bermewah-mewah, memamerkan kekayaan di media sosial (flexing), dan membeli barang bermerek luar negeri secara berlebihan bertentangan dengan nilai sila kelima Pancasila yaitu ...", ["Mengembangkan sikap hemat, sederhana, bersahaja, dan menghargai hasil kerja keras sesama", "Mendorong persaingan gengsi antarteman", "Menunjukkan martabat keluarga", "Memajukan ekonomi negara lain"], 0, "Sila kelima menentang pemborosan, gaya hidup hedonis, dan kesenjangan sosial yang mencolok.");
addQ("pan-k5-u16", 5, "Peran Lembaga Komisi Pemberantasan Korupsi (KPK)", "sulit", "Korupsi dikategorikan sebagai kejahatan luar biasa (extraordinary crime) karena merampas hak ekonomi rakyat miskin dan merusak sendi-sendi negara. Lembaga khusus yang bertugas menyelidiki dan menuntut tindak pidana korupsi adalah ...", ["Komisi Pemberantasan Korupsi (KPK)", "Komisi Penyiaran Indonesia (KPI)", "Komisi Perlindungan Anak Indonesia (KPAI)", "Komisi Yudisial (KY)"], 0, "KPK dibentuk khusus untuk memberantas korupsi secara terpadu dan profesional.");
addQ("pan-k5-u17", 5, "Analisis Hubungan Lembaga Negara Eksekutif dan Legislatif", "sulit", "Rancangan Undang-Undang (RUU) APBN diajukan oleh Presiden (eksekutif) untuk dibahas dan dimintakan persetujuan bersama kepada DPR (legislatif). Mekanisme ini menerapkan prinsip tata kelola kenegaraan yaitu ...", ["Checks and balances (saling mengawasi dan mengimbangi kekuasaan)", "Pemusatan kekuasaan mutlak pada presiden", "Pemberian kebebasan DPR mengatur keuangan sendiri", "Penghapusan fungsi menteri keuangan"], 0, "Checks and balances mencegah penyalahgunaan anggaran keuangan negara.");
addQ("pan-k5-u18", 5, "Tanggung Jawab Moral Pelajar Terhadap Sejarah Pahlawan", "sulit", "Bung Karno pernah berpesan: 'Jasmerah' (Jangan sekali-kali meninggalkan sejarah). Pesan ini mengingatkan generasi muda agar ...", ["Menghargai jasa perjuangan para pahlawan dan meneruskan cita-cita kemerdekaan bangsa", "Hanya menghafal tahun peristiwa bersejarah untuk ujian", "Menyimpan foto pahlawan di laci tertutup", "Mendendam kepada negara bekas penjajah"], 0, "Memahami sejarah menumbuhkan kecintaan patriotik dan fondasi jati diri bangsa.");
addQ("pan-k5-u19", 5, "Etika Mengkritik Kebijakan Publik", "sulit", "Ketika warga masyarakat merasa tidak puas dengan suatu kebijakan pelayanan publik di kantor kelurahan, cara menyampaikan aspirasi yang sesuai dengan nilai Pancasila adalah ...", ["Menyampaikan kritik yang santun, objektif, berdasar data fakta, melalui kotak saran atau audiensi resmi", "Merusak meja dan komputer kantor kelurahan", "Menyebarkan fitnah fitnah di grup media sosial", "Mengancam keselamatan petugas pelayanan"], 0, "Kritik konstruktif disampaikan secara beradab dan berlandaskan bukti.");
addQ("pan-k5-u20", 5, "Analisis Pasal 28 UUD 1945 tentang Hak Berserikat", "sulit", "Pasal 28 UUD 1945 menjamin kemerdekaan berserikat dan berkumpul, mengeluarkan pikiran dengan lisan dan tulisan. Di lingkungan sekolah, wujud penerapan hak ini adalah kebebasan murid untuk ...", ["Memilih dan aktif mengikuti kegiatan organisasi kesiswaan (OSIS/Pramuka) secara tertib", "Membuat geng tawuran antarsekolah", "Membolos bersama-sama dari jam pelajaran", "Memaksa teman masuk perkumpulan rahasia"], 0, "Organisasi kesiswaan resmi melatih kepemimpinan dan nilai-nilai demokrasi.");
addQ("pan-k5-u21", 5, "Makna Bela Negara Non-Fisik Pelajar", "sulit", "Seorang atlet renang cilik Indonesia berlatih keras hingga berhasil meraih medali emas di kejuaraan renang internasional dan mengibarkan Sang Merah Putih diiringi lagu Indonesia Raya. Prestasi atlet ini merupakan wujud nyata ...", ["Bela negara non-fisik yang mengharumkan martabat dan kehormatan bangsa di pentas dunia", "Pamer kekuatan otot", "Keberuntungan yang kebetulan", "Mencari hadiah uang pribadi saja"], 0, "Mengharumkan nama bangsa di ajang internasional adalah wujud bela negara prestisius.");
addQ("pan-k5-u22", 5, "Kearifan Budaya Pelestarian Air di Lereng Gunung", "sulit", "Masyarakat di lereng Gunung Merapi menjaga kawasan hutan lindung di puncak sebagai daerah resapan air keramat yang tidak boleh ditebangi pohonnya. Nilai ekologis dari kearifan budaya ini adalah ...", ["Menjaga ketersediaan mata air abadi bagi kehidupan warga di hilir dan mencegah bahaya longsor", "Menjadikan puncak gunung tempat tinggal para raksasa", "Melarang warga mandi dengan air bersih", "Menghalangi wisatawan mendaki gunung"], 0, "Kearifan lokal menyelaraskan hubungan manusia dengan alam (ekologi berkelanjutan).");
addQ("pan-k5-u23", 5, "Analisis Pentingnya Pajak Bagi Pembangunan Nasional", "sulit", "Pajak merupakan sumber pendapatan terbesar negara dalam APBN. Slogan 'Orang Bijak Taat Pajak' menegaskan bahwa kepatuhan membayar pajak merupakan wujud ...", ["Gotong royong warga negara membiayai fasilitas pendidikan, jalan, jembatan, dan pertahanan negara", "Beban paksaan tanpa ada manfaatnya", "Sumbangan sukarela jika ada sisa uang", "Pemberian hadiah untuk petugas pajak"], 0, "Pajak adalah wujud gotong royong modern untuk membiayai pembangunan bangsa.");
addQ("pan-k5-u24", 5, "Perlindungan Hak Kaum Rentan dan Disabilitas", "sulit", "Pemerintah kota mewajibkan trotoar jalan dilengkapi dengan ubin pemandu (guiding block) berwarna kuning bertekstur garis dan titik. Fasilitas ini dibangun untuk memenuhi hak mobilitas ...", ["Penyandang disabilitas tuna netra agar dapat berjalan dengan aman dan mandiri", "Pengendara sepeda motor yang ingin mendahului macet", "Pedagang kaki lima untuk menaruh gerobak", "Anak-anak bermain sepatu roda"], 0, "Guiding block adalah wujud keadilan ruang publik yang inklusif bagi tuna netra.");
addQ("pan-k5-u25", 5, "Sikap Menghargai Keberagaman Penganut Kepercayaan Terhadap Tuhan YME", "sulit", "Di Indonesia selain 6 agama resmi, terdapat para penghayat kepercayaan terhadap Tuhan YME yang dilindungi oleh putusan Mahkamah Konstitusi. Sikap warga negara yang berlandaskan Pancasila adalah ...", ["Menghormati hak mereka mencatatkan identitas kepercayaannya pada kolom KTP dan beribadah dengan tenang", "Memaksa mereka memilih salah satu agama mayoritas", "Mengucilkan mereka dari lingkungan pergaulan", "Melarang anak-anak mereka bersekolah"], 0, "Semua warga negara dilindungi hak keyakinannya oleh hukum dan konstitusi.");
addQ("pan-k5-u26", 5, "Analisis Batas Laut Teritorial Indonesia", "sulit", "Deklarasi Djuanda tanggal 13 Desember 1957 merupakan tonggak sejarah penting yang menyatakan bahwa laut di antara dan di dalam kepulauan Indonesia adalah ...", ["Satu kesatuan wilayah kedaulatan mutlak NKRI, bukan perairan internasional bebas", "Milik negara penjajah Belanda", "Perairan bebas yang boleh dikuasai kapal perang asing mana pun", "Wilayah sengketa tanpa pemilik"], 0, "Deklarasi Djuanda melipatgandakan luas wilayah kedaulatan RI dan menyatukan kepulauan nusantara.");
addQ("pan-k5-u27", 5, "Peringatan Hari Pahlawan 10 November", "sulit", "Pertempuran dahsyat di Surabaya tanggal 10 November 1945 diperingati sebagai Hari Pahlawan. Nilai keteladanan yang dikobarkan oleh Bung Tomo melalui pidato radionya adalah ...", ["Semangat patriotisme pantang menyerah membela kedaulatan tanah air dari penjajah", "Keinginan berkuasa di seluruh Jawa Timur", "Kebencian terhadap orang asing secara membabi buta", "Semangat melarikan diri dari medan pertempuran"], 0, "Arek-arek Suroboyo membuktikan patriotisme dan keberanian tanpa gentar mempertahankan kemerdekaan.");
addQ("pan-k5-u28", 5, "Tanggung Jawab Pemenuhan Hak Asasi Anak", "sulit", "Konvensi Hak Anak yang diratifikasi Indonesia mencakup hak hidup, hak tumbuh kembang, hak perlindungan, dan hak partisipasi. Pihak yang paling pertama dan utama bertanggung jawab memenuhi hak-hak tersebut adalah ...", ["Orang tua dan keluarga terdekat", "Polisi pamong praja", "Guru les privat", "Tetangga jauh"], 0, "Keluarga adalah lingkungan pertama dan fondasi utama tumbuh kembang anak.");
addQ("pan-k5-u29", 5, "Penyelesaian Sengketa Pemilu di Mahkamah Konstitusi", "sulit", "Jika peserta pemilihan umum menduga terjadi kecurangan hasil penghitungan suara, jalur hukum konstitusional yang sah dan beradab adalah ...", ["Mengajukan gugatan sengketa hasil pemilu ke Mahkamah Konstitusi disertai bukti-bukti yang sah", "Mengajak para pendukung melakukan kerusuhan di jalanan", "Membakar kantor Komisi Pemilihan Umum", "Memaksa panitia pemilu mengubah angka suara"], 0, "Penyelesaian sengketa pemilu di MK menjamin transisi kekuasaan secara damai dan konstitusional.");
addQ("pan-k5-u30", 5, "Pancasila Sebagai Sumber dari Segala Sumber Hukum", "sulit", "Makna kedudukan Pancasila sebagai sumber dari segala sumber hukum negara diatur dalam UU No. 12 Tahun 2011. Konsekuensinya adalah ...", ["Semua peraturan perundang-undangan di Indonesia tidak boleh bertentangan dengan nilai-nilai Pancasila", "Pancasila dapat diubah oleh keputusan presiden sewaktu-waktu", "Undang-Undang kedudukannya lebih tinggi daripada Pancasila", "Hukum adat tidak boleh diberlakukan"], 0, "Pancasila adalah norma fundamental negara (staatsfundamentalnorm) yang menjiwai seluruh hukum nasional.");

console.log("Kelas 5 Pancasila ready: " + allQuestions.length + " questions.");

addQ("pan-k6-m01", 6, "Sejarah Lahirnya Pancasila", "mudah", "Hari Lahir Pancasila diperingati setiap tanggal ...", ["1 Juni", "17 Agustus", "1 Oktober", "28 Oktober"], 0, "1 Juni diperingati sebagai Hari Lahir Pancasila merujuk pada pidato Bung Karno tahun 1945.");
addQ("pan-k6-m02", 6, "Hari Kesaktian Pancasila", "mudah", "Hari Kesaktian Pancasila diperingati setiap tanggal ...", ["1 Oktober", "1 Juni", "10 November", "20 Mei"], 0, "1 Oktober diperingati sebagai Hari Kesaktian Pancasila.");
addQ("pan-k6-m03", 6, "Hari Kebangkitan Nasional", "mudah", "Hari Kebangkitan Nasional diperingati pada tanggal 20 Mei bertepatan dengan berdirinya organisasi pemuda ...", ["Budi Utomo", "Sarekat Islam", "Indische Partij", "Muhammadiyah"], 0, "Budi Utomo didirikan 20 Mei 1908 oleh dr. Soetomo dan para pelajar STOVIA.");
addQ("pan-k6-m04", 6, "Hari Sumpah Pemuda", "mudah", "Hari Sumpah Pemuda diperingati setiap tahun pada tanggal ...", ["28 Oktober", "17 Agustus", "21 April", "10 November"], 0, "Kongres Pemuda II mengikrarkan Sumpah Pemuda pada 28 Oktober 1928.");
addQ("pan-k6-m05", 6, "Badan Penyelidik Kemerdekaan (BPUPKI)", "mudah", "BPUPKI dibentuk pada 1 Maret 1945 untuk menyelidiki usaha-usaha persiapan kemerdekaan Indonesia. BPUPKI dipimpin oleh ...", ["Dr. K.R.T. Radjiman Wedyodiningrat", "Ir. Soekarno", "Drs. Mohammad Hatta", "Mr. Soepomo"], 0, "Dr. Radjiman Wedyodiningrat bertindak sebagai ketua BPUPKI.");
addQ("pan-k6-m06", 6, "Panitia Persiapan Kemerdekaan Indonesia (PPKI)", "mudah", "PPKI dibentuk pada tanggal 7 Agustus 1945 untuk mempersiapkan kemerdekaan Indonesia. Ketua PPKI adalah ...", ["Ir. Soekarno", "Mohammad Hatta", "Achmad Soebardjo", "Ki Hajar Dewantara"], 0, "Ir. Soekarno adalah ketua PPKI didampingi Drs. Moh. Hatta sebagai wakil ketua.");
addQ("pan-k6-m07", 6, "Sidang Pertama PPKI 18 Agustus 1945", "mudah", "Salah satu keputusan terpenting sidang PPKI pada tanggal 18 Agustus 1945 adalah mengesahkan ...", ["UUD 1945 dan memilih Ir. Soekarno serta Drs. Moh. Hatta sebagai Presiden dan Wakil Presiden", "Teks Proklamasi Kemerdekaan", "Piagam Jakarta tanpa perubahan", "Undang-Undang Pertambangan"], 0, "PPKI mengesahkan UUD 1945 dan memilih Presiden dan Wakil Presiden pertama RI.");
addQ("pan-k6-m08", 6, "Tokoh Perumus Teks Proklamasi", "mudah", "Teks naskah Proklamasi Kemerdekaan Indonesia disusun di kediaman Laksamana Muda Maeda oleh tiga tokoh utama yaitu ...", ["Ir. Soekarno, Drs. Moh. Hatta, dan Mr. Achmad Soebardjo", "Ki Hajar Dewantara, Raden Ajeng Kartini, dan Dewi Sartika", "Jenderal Soedirman, Bung Tomo, dan Sayuti Melik", "Sutan Sjahrir, Amir Sjarifuddin, dan Tan Malaka"], 0, "Soekarno, Hatta, dan Achmad Soebardjo merumuskan naskah Proklamasi di Jl. Imam Bonjol No. 1.");
addQ("pan-k6-m09", 6, "Pengetik Naskah Proklamasi", "mudah", "Naskah proklamasi yang telah disepakati diketik menggunakan mesin tik oleh seorang pemuda pejuang bernama ...", ["Sayuti Melik", "Sukarni", "B.M. Diah", "Chaerul Saleh"], 0, "Sayuti Melik mengetik naskah proklamasi dengan beberapa perubahan kata.");
addQ("pan-k6-m10", 6, "Penjahit Bendera Pusaka Merah Putih", "mudah", "Bendera pusaka Sang Saka Merah Putih yang dikibarkan saat proklamasi 17 Agustus 1945 dijahit oleh ...", ["Ibu Fatmawati Soekarno", "Ibu R.A. Kartini", "Cut Nyak Dien", "Dewi Sartika"], 0, "Ibu Fatmawati menjahit bendera pusaka Merah Putih.");

addQ("pan-k6-s01", 6, "Tiga Tokoh Pengusul Dasar Negara di BPUPKI", "sedang", "Tiga tokoh bangsa yang mengemukakan gagasannya mengenai dasar negara pada sidang BPUPKI tanggal 29 Mei - 1 Juni 1945 adalah ...", ["Mr. Mohammad Yamin, Mr. Soepomo, dan Ir. Soekarno", "Bung Hatta, Bung Tomo, dan Sjahrir", "Radjiman, Sayuti Melik, dan Sukarni", "Tan Malaka, Amir Sjarifuddin, dan Muso"], 0, "Mohammad Yamin (29 Mei), Soepomo (31 Mei), dan Soekarno (1 Juni) mengusulkan konsep dasar negara.");
addQ("pan-k6-s02", 6, "Panitia Sembilan dan Piagam Jakarta", "sedang", "Panitia Sembilan dibentuk pada 22 Juni 1945 dan menghasilkan naskah rancangan pembukaan UUD yang dikenal dengan nama ...", ["Piagam Jakarta (Jakarta Charter)", "Dekrit Presiden", "Supersemar", "Maklumat Pemerintah"], 0, "Panitia Sembilan merumuskan Piagam Jakarta yang memuat rancangan dasar negara.");
addQ("pan-k6-s03", 6, "Perubahan Kalimat Sila Pertama Piagam Jakarta", "sedang", "Demi menjaga persatuan dan keutuhan bangsa Indonesia yang majemuk, tujuh kata dalam sila pertama Piagam Jakarta diubah menjadi ...", ["Ketuhanan Yang Maha Esa", "Ketuhanan dengan kewajiban menjalankan syariat Islam", "Ketuhanan yang berkebudayaan", "Ketuhanan yang maha pengasih"], 0, "Tujuh kata dalam Piagam Jakarta diubah demi menjaga integrasi bangsa dari Sabang sampai Merauke.");
addQ("pan-k6-s04", 6, "Makna Peristiwa Rengasdengklok", "sedang", "Tujuan para pemuda (seperti Sukarni dan Chaerul Saleh) membawa Soekarno dan Hatta ke Rengasdengklok pada 16 Agustus 1945 adalah ...", ["Menjauhkan kedua tokoh dari pengaruh Jepang dan mendesak proklamasi segera diumumkan", "Menyandera mereka untuk meminta uang tebusan", "Menyembunyikan mereka dari tentara sekutu", "Mengajak berlibur di pedesaan"], 0, "Pemuda mendesak agar proklamasi kemerdekaan murni hasil perjuangan bangsa Indonesia sendiri.");
addQ("pan-k6-s05", 6, "Pembaca Teks Proklamasi", "sedang", "Teks Proklamasi Kemerdekaan Republik Indonesia dibacakan pada hari Jumat, 17 Agustus 1945 pukul 10.00 pagi di ...", ["Jalan Pegangsaan Timur No. 56, Jakarta", "Istana Merdeka, Jakarta", "Gedung DPR/MPR Senayan", "Lapangan Ikada"], 0, "Proklamasi dibacakan di halaman kediaman Bung Karno, Jalan Pegangsaan Timur 56 Jakarta.");
addQ("pan-k6-s06", 6, "Pengibar Bendera Proklamasi", "sedang", "Tokoh pemuda yang bertugas mengibarkan bendera Merah Putih pertama kali saat upacara proklamasi kemerdekaan adalah ...", ["Latief Hendraningrat dan Suhud Sastro Kusumo", "Sayuti Melik dan B.M. Diah", "Sukarni dan Chaerul Saleh", "Adam Malik dan Roeslan Abdulgani"], 0, "Latief Hendraningrat bersama Suhud mengibarkan Sang Saka Merah Putih diiringi lagu Indonesia Raya.");
addQ("pan-k6-s07", 6, "Nilai Rela Berkorban Para Pahlawan", "sedang", "Sikap para pejuang kemerdekaan yang bersedia mengorbankan harta, waktu, tenaga, bahkan nyawa demi terwujudnya kemerdekaan Indonesia merupakan wujud nilai ...", ["Rela berkorban (patriotisme tanpa pamrih)", "Mencari kedudukan jabatan tinggi", "Kepentingan golongan tertentu", "Ambisi memperkaya keturunan"], 0, "Pengorbanan tulus para pahlawan adalah teladan luhur nasionalisme.");
addQ("pan-k6-s08", 6, "Nilai Musyawarah Mufakat Pendiri Bangsa", "sedang", "Sikap para pendiri bangsa yang bersedia menerima perubahan rumusan sila pertama Piagam Jakarta demi keutuhan wilayah Indonesia Timur mencerminkan sikap ...", ["Toleransi tinggi, jiwa besar, dan mendahulukan persatuan bangsa di atas kepentingan golongan", "Kelemahan dan kepasrahan", "Kekalahan dalam berdebat", "Ketidakpedulian terhadap agama"], 0, "Keberhasilan kompromi luhur demi persatuan nasional adalah mahakarya para founding fathers.");
addQ("pan-k6-s09", 6, "Pancasila Sebagai Ideologi Terbuka", "sedang", "Pancasila disebut sebagai ideologi terbuka karena nilai-nilai dasarnya bersifat tetap, namun penjabaran nilai instrumennya mampu ...", ["Menyesuaikan diri dengan perkembangan zaman, ilmu pengetahuan, dan dinamika aspirasi masyarakat", "Berubah-ubah sesuai kehendak presiden yang menjabat", "Menerima paham komunisme dan liberalisme bebas", "Digantikan oleh ideologi negara lain"], 0, "Ideologi terbuka dinamis dan mampu menjawab tantangan kemajuan zaman tanpa kehilangan jati dirinya.");
addQ("pan-k6-s10", 6, "Dimensi Realitas Pancasila", "sedang", "Dimensi ideologi yang menyatakan bahwa nilai-nilai dasar Pancasila bersumber dan hidup berakar dari nilai-nilai nyata masyarakat Indonesia dinamakan dimensi ...", ["Realitas", "Idealisme", "Normatif", "Fleksibilitas"], 0, "Dimensi realitas menegaskan nilai Pancasila berakar dari budaya asli kepribadian nusantara.");
addQ("pan-k6-s11", 6, "Dimensi Idealisme Pancasila", "sedang", "Dimensi Pancasila yang memuat cita-cita luhur dan harapan masa depan yang ingin diwujudkan bangsa Indonesia dalam berbagai bidang kehidupan dinamakan dimensi ...", ["Idealisme", "Realitas", "Praktis", "Birokrasi"], 0, "Dimensi idealisme memberikan optimisme dan harapan mewujudkan masyarakat adil makmur.");
addQ("pan-k6-s12", 6, "Dimensi Fleksibilitas Pancasila", "sedang", "Dimensi Pancasila yang memiliki kemampuan untuk berkembang, memperbarui pemikiran konseptual, dan terbuka terhadap perubahan yang positif disebut dimensi ...", ["Fleksibilitas (pengembangan)", "Kekakuan", "Statis", "Tertutup"], 0, "Dimensi fleksibilitas menjaga relevansi Pancasila melintasi abad dan generasi.");
addQ("pan-k6-s13", 6, "Peran Indonesia dalam Organisasi ASEAN", "sedang", "Indonesia adalah salah satu dari lima negara pemrakarsa berdirinya ASEAN melalui Deklarasi Bangkok pada 8 Agustus 1967. Tokoh perwakilan dari Indonesia adalah ...", ["Adam Malik", "Tun Abdul Razak", "Narciso Ramos", "S. Rajaratnam"], 0, "Adam Malik (Menteri Luar Negeri RI) menandatangani Deklarasi Bangkok mewakili Indonesia.");
addQ("pan-k6-s14", 6, "Politik Luar Negeri Bebas Aktif", "sedang", "Prinsip politik luar negeri Indonesia adalah 'Bebas dan Aktif'. Makna kata 'Bebas' adalah ...", ["Tidak memihak pada salah satu blok kekuatan dunia mana pun yang bersengketa", "Bebas berbuat sesuka hati menjajah bangsa lain", "Bebas memutuskan hubungan diplomatik", "Bebas menyatakan perang kapan saja"], 0, "Bebas berarti Indonesia berdaulat menentukan jalannya tanpa didikte blok kekuatan adidaya.");
addQ("pan-k6-s15", 6, "Makna Kata Aktif dalam Politik Luar Negeri", "sedang", "Makna kata 'Aktif' dalam politik luar negeri bebas aktif Indonesia adalah ...", ["Turut aktif memperjuangkan terciptanya perdamaian dunia dan meredakan ketegangan internasional", "Aktif mengirim tentara untuk menyerang negara lain", "Aktif mencampuri urusan dalam negeri bangsa lain", "Aktif membeli senjata nuklir"], 0, "Aktif berpartisipasi menjaga ketertiban dunia berdasarkan kemerdekaan, perdamaian abadi, dan keadilan sosial.");
addQ("pan-k6-s16", 6, "Konferensi Tingkat Tinggi Asia Afrika (KAA) 1955", "sedang", "Indonesia menjadi tuan rumah Konferensi Asia Afrika (KAA) di Bandung pada tahun 1955 yang melahirkan Dasasila Bandung. KAA bertujuan untuk ...", ["Membantu perjuangan bangsa-bangsa di Asia dan Afrika melepaskan diri dari belenggu penjajahan", "Membentuk aliansi militer perang dingin", "Membagi wilayah jajahan baru", "Menguasai perdagangan minyak dunia"], 0, "KAA membangkitkan gelombang dekolonisasi kemerdekaan negara-negara Asia-Afrika.");
addQ("pan-k6-s17", 6, "Pasukan Perdamaian Garuda (Kontingen Garuda)", "sedang", "Indonesia aktif mengirimkan pasukan perdamaian TNI di bawah naungan PBB ke wilayah konflik di dunia (seperti Lebanon, Kongo). Pasukan ini dikenal dengan sebutan ...", ["Kontingen Garuda (Pasukan Garuda)", "Komando Rajawali", "Laskar Harimau", "Batalyon Macan"], 0, "Kontingen Garuda adalah duta militer perdamaian bangsa Indonesia di bawah mandat PBB.");
addQ("pan-k6-s18", 6, "Gerakan Non-Blok (GNB)", "sedang", "Indonesia menjadi salah satu pelopor berdirinya Gerakan Non-Blok (GNB) bersama Yugoslavia, Mesir, India, dan Ghana pada tahun 1961 untuk meredakan persaingan antara ...", ["Blok Barat (Amerika Serikat) dan Blok Timur (Uni Soviet)", "Negara-negara di benua Eropa dan Afrika", "Negara berkembang dan negara miskin", "Jepang dan Cina"], 0, "GNB dibentuk saat Perang Dingin meruncing antara Blok Barat dan Blok Timur.");
addQ("pan-k6-s19", 6, "Peran Indonesia Menjaga Laut Natuna", "sedang", "Pemerintah Indonesia menegakkan kedaulatan di Zona Ekonomi Eksklusif (ZEE) perairan Natuna Utara dari ancaman klaim sepihak kapal asing. Upaya ini berlandaskan pada hukum laut internasional ...", ["UNCLOS 1982 (United Nations Convention on the Law of the Sea)", "Piagam Atlantik", "Perjanjian Versailles", "Deklarasi Kyoto"], 0, "UNCLOS 1982 mengakui kedaulatan hak berdaulat maritim ZEE Indonesia.");
addQ("pan-k6-s20", 6, "Menolak Penyalahgunaan Narkoba Pelajar", "sedang", "Ancaman kejahatan narkoba dan obat-obatan terlarang merusak daya pikir dan moral generasi muda bangsa. Sikap tegas seorang pelajar berkarakter Pancasila adalah ...", ["Menolak dengan tegas segala bentuk tawaran narkoba dan aktif berprestasi positif", "Mencoba sedikit karena penasaran", "Menyimpan barang terlarang milik teman", "Ikut menjual agar mendapat uang saku"], 0, "Karakter Pancasila membentengi generasi muda dari racun narkotika.");

addQ("pan-k6-u01", 6, "Analisis Kritis Peristiwa Rengasdengklok", "sulit", "Peristiwa Rengasdengklok sering disalahpahami sebagai penculikan bermotif kekerasan, padahal esensi sejarah yang sebenarnya adalah ...", ["Wujud kemandirian dan keberanian kaum muda agar Proklamasi 17 Agustus 1945 murni lahir dari kehendak bangsa Indonesia tanpa campur tangan janji kemerdekaan Jepang", "Perebutan kekuasaan antara generasi tua dan generasi muda", "Perselisihan senjata antara PETA dan Heiho", "Keinginan kaum muda mendirikan negara terpisah di Karawang"], 0, "Pemuda ingin menegaskan kemerdekaan Indonesia bukan 'hadiah' dari Marsekal Terauchi/Jepang melainkan hasil perjuangan tumpah darah sendiri.");
addQ("pan-k6-u02", 6, "Analisis Kompromi Kebangsaan 18 Agustus 1945", "sulit", "Pada tanggal 18 Agustus 1945 pagi sebelum sidang PPKI dibuka, Bung Hatta menemui tokoh-tokoh Islam (seperti Ki Bagus Hadikusumo, Wahid Hasyim, Kasman Singodimedjo) untuk mengusulkan perubahan sila pertama Piagam Jakarta. Sikap kenegarawanan para tokoh Islam yang menerima usulan tersebut membuktikan bahwa ...", ["Para pemimpin Islam menempatkan keutuhan, keselamatan, dan persatuan NKRI di atas kepentingan eksklusif kelompok", "Tokoh Islam tidak memiliki pendirian yang kuat", "Adanya ancaman militer dari tentara sekutu", "Sidang PPKI dipaksa oleh pihak asing"], 0, "Keikhlasan dan kebesaran jiwa tokoh Islam menyelamatkan integrasi wilayah Indonesia dari ancaman pemisahan diri kawasan timur.");
addQ("pan-k6-u03", 6, "Analisis Makna Kedaulatan Rakyat Pasca Amandemen UUD 1945", "sulit", "Sebelum amandemen UUD 1945, kedaulatan rakyat dilakukan sepenuhnya oleh MPR. Namun setelah amandemen, Pasal 1 ayat (2) berbunyi: 'Kedaulatan berada di tangan rakyat dan dilaksanakan menurut Undang-Undang Dasar.' Perubahan mendasar ini mengakibatkan ...", ["Presiden dan anggota legislatif dipilih langsung oleh rakyat melalui pemilihan umum yang demokratis", "MPR menjadi lembaga tertinggi negara yang kebal hukum", "Presiden berkuasa seumur hidup tanpa batas", "Rakyat tidak perlu lagi mengikuti pemilu"], 0, "Kedaulatan rakyat kini dijalankan melalui mekanisme pembagian kekuasaan konstitusional dan pemilu langsung.");
addQ("pan-k6-u04", 6, "Analisis Makna Teori Trias Politika di Indonesia", "sulit", "Sistem ketatanegaraan Indonesia membagi kekuasaan ke dalam tiga cabang utama (legislatif, eksekutif, dan yudikatif) namun tidak menerapkan pemisahan mutlak (separation of powers) melainkan pembagian kekuasaan (distribution of powers). Tujuannya adalah ...", ["Memungkinkan adanya kerjasama yang harmonis serta mekanisme saling kontrol dan mengimbangi (checks and balances)", "Membuat kekuasaan eksekutif tidak terkontrol oleh lembaga lain", "Mencegah presiden membuat rancangan undang-undang", "Menghapus pengadilan peradilan"], 0, "Indonesia menerapkan pembagian kekuasaan yang saling berkoordinasi dan mengawasi.");
addQ("pan-k6-u05", 6, "Analisis Bahaya Politik Identitas SARA dalam Pemilu", "sulit", "Penggunaan politik identitas yang mengeksploitasi perbedaan Suku, Agama, Ras, dan Antargolongan (SARA) untuk memenangkan calon tertentu dalam pemilu sangat dilarang karena berakibat fatal yaitu ...", ["Memecah belah persaudaraan kebangsaan, memicu konflik horizontal bernuansa kekerasan, dan mengoyak persatuan nasional", "Meningkatkan kecerdasan politik para pemilih", "Membuat pemilu berlangsung lebih murah", "Menjadikan pemenang pemilu disukai seluruh dunia"], 0, "Politisasi SARA merusak kohesi sosial dan melanggar prinsip dasar persatuan Indonesia.");
addQ("pan-k6-u06", 6, "Analisis Makna Bhinneka Tunggal Ika Tan Hana Dharma Mangrwa", "sulit", "Semboyan lengkap dalam Kitab Sutasoma karya Mpu Tantular adalah 'Bhinneka Tunggal Ika Tan Hana Dharma Mangrwa'. Frasa 'Tan Hana Dharma Mangrwa' memiliki makna filosofis yang mendalam yaitu ...", ["Tiada kebenaran yang mendua (pada hakikatnya semua kebaikan bermuara pada Yang Satu)", "Tidak ada raja yang adil di dunia", "Hanya satu hukum yang berlaku untuk seluruh jagat", "Perbedaan itu selamanya tidak bisa disatukan"], 0, "Mpu Tantular menegaskan keharmonisan spiritual antara Siwa dan Buddha di era Majapahit bermuara pada satu kebenaran hakiki.");
addQ("pan-k6-u07", 6, "Analisis Keteladanan Jenderal Soedirman", "sulit", "Dalam keadaan sakit paru-paru parah dan harus ditandu keluar masuk hutan belantara, Panglima Besar Jenderal Soedirman tetap memimpin perang gerilya melawan Agresi Militer Belanda II. Nilai karakter luhur yang ditunjukkan oleh Jenderal Soedirman adalah ...", ["Keteguhan iman, pantang menyerah, dan kesetiaan mutlak kepada kedaulatan tanah air", "Keinginan menuntut kenaikan gaji dari pemerintah", "Keputusasaan menghadapi musuh", "Kebanggaan atas senjata rampasan"], 0, "Panglima Soedirman mencontohkan pengorbanan tanpa batas dan loyalitas tertinggi kepada republik.");
addQ("pan-k6-u08", 6, "Analisis Keteladanan Mohammad Hatta Tentang Kesederhanaan", "sulit", "Bung Hatta yang merupakan proklamator dan Wakil Presiden RI pertama dikenal sangat jujur, hidup sederhana, dan hingga akhir hayatnya tidak mampu membeli sepatu Bally impiannya karena uang pensiunnya disumbangkan untuk orang yang membutuhkan. Keteladanan Bung Hatta adalah antitesis dari perilaku ...", ["Korupsi, kolusi, nepotisme, dan gaya hidup bermewah-mewah dari uang rakyat", "Kerja keras menuntut ilmu di luar negeri", "Kedisiplinan mengatur waktu membaca buku", "Cinta kepada koperasi rakyat"], 0, "Integritas moral dan kesederhanaan Bung Hatta adalah standar keteladanan tertinggi pejabat publik.");
addQ("pan-k6-u09", 6, "Analisis Keteladanan Ki Hajar Dewantara dalam Pendidikan", "sulit", "Semboyan pendidikan nasional dari Ki Hajar Dewantara adalah: 'Ing ngarso sung tulodo, ing madyo mangun karso, tut wuri handayani'. Makna mendalam dari 'Ing ngarso sung tulodo' bagi seorang pemimpin bangsa adalah ...", ["Di depan harus mampu memberikan teladan akhlak dan perbuatan yang baik", "Di depan berhak mengambil bagian rezeki terbanyak", "Di depan boleh memerintah bawahan tanpa bekerja", "Di depan harus terlihat paling berkuasa"], 0, "Pemimpin sejati memimpin dengan memberi keteladanan moral nyata.");
addQ("pan-k6-u10", 6, "Analisis Keteladanan R.A. Kartini dan Dewi Sartika", "sulit", "Perjuangan Raden Ajeng Kartini di Jepara dan Raden Dewi Sartika di Bandung sama-sama gigih memperjuangkan emansipasi wanita melalui jalur ...", ["Pendidikan dan pengajaran agar kaum perempuan memiliki kecerdasan, martabat, dan kemandirian", "Pemberontakan militer bersenjata", "Tuntutan politik menguasai kerajaan", "Menolak kebudayaan lokal daerah"], 0, "Pendidikan memerdekakan kaum wanita dari kebodohan dan keterbelakangan.");
addQ("pan-k6-u11", 6, "Analisis Tantangan Globalisasi Terhadap Budaya Lokal", "sulit", "Masuknya gelombang budaya asing (seperti demam K-Pop, pergaulan bebas, dan individualisme) dapat mengikis kecintaan generasi muda pada seni budaya lokal jika anak bangsa bersikap ...", ["Menerima secara membabi buta tanpa menyaring dengan nilai-nilai luhur Pancasila", "Mempelajari budaya asing untuk memperkaya pengetahuan bahasa", "Menampilkan tarian tradisional di panggung pentas internasional", "Menciptakan kolaborasi musik daerah dengan aransemen modern"], 0, "Ketiadaan filter budaya membuat generasi muda kehilangan jati diri kebangsaan.");
addQ("pan-k6-u12", 6, "Analisis Sikap Patriotisme Positif vs Chauvinisme", "sulit", "Rasa cinta tanah air yang berlebihan hingga memandang bangsanya paling agung dan merendahkan martabat bangsa-bangsa lain di dunia dinamakan paham ...", ["Chauvinisme sempit", "Nasionalisme Pancasila", "Patriotisme luhur", "Internasionalisme"], 0, "Chauvinisme adalah nasionalisme sempit yang agresif dan memicu perang antarnegara.");
addQ("pan-k6-u13", 6, "Analisis Kedudukan Peraturan Perundang-Undangan di Indonesia", "sulit", "Berdasarkan hierarki peraturan perundang-undangan (UU No. 12 Tahun 2011), urutan tata perundangan dari tingkat tertinggi ke yang lebih rendah adalah ...", ["UUD 1945 -> Tap MPR -> UU/Perppu -> PP -> Perpres -> Perda Provinsi -> Perda Kab/Kota", "UU -> UUD 1945 -> Perpres -> PP -> Perda", "Tap MPR -> UUD 1945 -> PP -> UU -> Perda", "Perda -> Perpres -> PP -> UU -> UUD 1945"], 0, "UUD 1945 adalah hukum dasar tertertinggi dalam piramida tata hukum Indonesia.");
addQ("pan-k6-u14", 6, "Analisis Peran Komisi Yudisial (KY)", "sulit", "Lembaga negara mandiri yang berwenang mengusulkan pengangkatan hakim agung dan menjaga serta menegakkan kehormatan, keluhuran martabat, dan perilaku hakim adalah ...", ["Komisi Yudisial (KY)", "Mahkamah Konstitusi (MK)", "Badan Pemeriksa Keuangan (BPK)", "Kejaksaan Agung"], 0, "KY mengawasi etika dan integritas moral para hakim di seluruh Indonesia.");
addQ("pan-k6-u15", 6, "Analisis Makna Keterbukaan Informasi Publik", "sulit", "Undang-Undang Keterbukaan Informasi Publik (UU KIP) menjamin hak warga negara untuk mengetahui rencana pembuatan kebijakan publik dan anggaran belanja pemerintah. Manfaat keterbukaan informasi ini adalah ...", ["Mewujudkan pemerintahan yang bersih, transparan, akuntabel, dan mencegah korupsi", "Membocorkan rahasia pertahanan militer kepada musuh", "Membuat pejabat pemerintah malas bekerja", "Menghapus kewajiban membayar pajak"], 0, "Transparansi adalah instrumen utama pencegahan penyelewengan kekuasaan.");
addQ("pan-k6-u16", 6, "Analisis Pentingnya Bela Negara Non-Militer Bagi Ilmuwan Muda", "sulit", "Seorang ilmuwan muda Indonesia berhasil menemukan varietas padi tahan kekeringan dan membagikan bibitnya secara cuma-cuma kepada kelompok tani nusantara. Tindakan ilmuwan ini merupakan perwujudan bela negara di bidang ...", ["Ketahanan pangan nasional dan kedaulatan ekonomi rakyat", "Pertahanan militer darat", "Diplomasi politik luar negeri", "Hukum perdata internasional"], 0, "Ketahanan pangan adalah benteng kedaulatan strategis bangsa dari ancaman krisis global.");
addQ("pan-k6-u17", 6, "Analisis Makna Piagam PBB Terkait Hak Menentukan Nasib Sendiri", "sulit", "Indonesia selalu lantang menyuarakan hak menentukan nasib sendiri (right to self-determination) bagi bangsa-bangsa terjajah dalam sidang Majelis Umum PBB. Landasan konstitusional dari sikap konsisten ini adalah ...", ["Pembukaan UUD 1945 alinea I yang menyatakan bahwa penjajahan di atas dunia harus dihapuskan", "Keinginan Indonesia diakui sebagai negara adidaya baru", "Perintah dari sekretaris jenderal PBB semata", "Keinginan membentuk aliansi perang baru"], 0, "Alinea I Pembukaan UUD 1945 adalah doktrin moral perikemanusiaan dan keadilan global.");
addQ("pan-k6-u18", 6, "Analisis Masalah Disparitas Pembangunan Wilayah 3T", "sulit", "Pemerintah menggencarkan pembangunan infrastruktur di kawasan Terdepan, Terluar, dan Tertinggal (3T) seperti di Natuna, Miangas, dan Rote. Tujuan pemerataan ini ditinjau dari sila ke-5 dan ke-3 adalah ...", ["Mewujudkan keadilan sosial bagi seluruh rakyat sekaligus memperkokoh keutuhan dan integrasi NKRI", "Memudahkan eksploitasi kekayaan alam untuk pihak asing", "Memindahkan seluruh penduduk pulau Jawa ke pulau terluar", "Membangun pangkalan militer pribadi"], 0, "Pembangunan di wilayah 3T menumbuhkan rasa keadilan dan menguatkan kedaulatan tapal batas negara.");
addQ("pan-k6-u19", 6, "Analisis Sikap Terhadap Provokasi di Media Sosial", "sulit", "Menjelang pemilihan umum sering beredar konten rekayasa digital (deepfake) dan ujaran fitnah yang bertujuan memicu permusuhan antarumat beragama. Sikap bijak seorang warganet berkarakter Pancasila adalah ...", ["Melakukan verifikasi fakta (cek fakta) melalui media kredibel, tidak ikut menyebarkan, dan melaporkan konten fitnah tersebut", "Menyebarkannya ke semua grup WhatsApp keluarga agar viral", "Membalas dengan ujaran kebencian yang lebih kejam", "Menghakimi secara sepihak tanpa mencari bukti"], 0, "Literasi digital kritis dan etis mencegah fragmentasi kerukunan nasional.");
addQ("pan-k6-u20", 6, "Analisis Hak Pilih Pemula dalam Menentukan Masa Depan Bangsa", "sulit", "Memilih pemimpin negara dalam pemilihan umum dengan meneliti rekam jejak integritas, visi misi, dan komitmen kerakyatan calon merupakan tanggung jawab warga negara untuk mewujudkan ...", ["Pemerintahan yang demokratis, amanah, dan berpihak pada kesejahteraan rakyat", "Kemenangan mutlak partai keluarga", "Kemudahan mendapatkan uang suap pemilu", "Kepentingan negara asing"], 0, "Gunakan hak pilih secara cerdas dan bebas dari praktik politik uang (money politics).");
addQ("pan-k6-u21", 6, "Analisis Makna Pasal 36A UUD 1945 tentang Lambang Negara", "sulit", "Pasal 36A UUD 1945 berbunyi: 'Lambang Negara ialah Garuda Pancasila dengan semboyan Bhinneka Tunggal Ika.' Pencantuman lambang negara dan semboyan ke dalam konstitusi negara bertujuan untuk ...", ["Mengikat secara hukum kehormatan simbol pemersatu kedaulatan bangsa Indonesia", "Memudahkan pencetakan uang kertas baru", "Meniru bendera kerajaan zaman kuno", "Hanya sebagai pelengkap teks undang-undang"], 0, "Lambang negara adalah simbol identitas kedaulatan dan kehormatan bangsa yang wajib dihormati.");
addQ("pan-k6-u22", 6, "Analisis Bentuk Kerjasama Ekonomi Internasional yang Berkeadilan", "sulit", "Dalam perundingan perdagangan global (WTO), Indonesia bersikeras melarang ekspor bijih nikel mentah dan mewajibkan hilirisasi industri di dalam negeri. Kebijakan kedaulatan ekonomi ini berakar dari pengamalan UUD 1945 Pasal 33 ayat (3) demi ...", ["Memberikan nilai tambah ekonomi tinggi dan membuka lapangan kerja seluas-luasnya bagi rakyat Indonesia", "Menutup diri dari pergaulan perdagangan dunia", "Menghabiskan nikel secepat mungkin", "Membuat harga baterai listrik menjadi sangat mahal"], 0, "Hilirisasi mengoptimalkan kekayaan alam demi kemakmuran sebesar-besar rakyat sendiri.");
addQ("pan-k6-u23", 6, "Analisis Pentingnya Amandemen UUD 1945", "sulit", "UUD 1945 diamandemen sebanyak 4 kali pada kurun waktu 1999–2002 oleh MPR. Latar belakang utama dilakukannya amandemen tersebut adalah ...", ["Membatasi kekuasaan presiden agar tidak otoriter, memperkuat sistem checks and balances, dan memperluas jaminan HAM", "Mengganti bentuk Negara Kesatuan Republik Indonesia", "Menghapuskan dasar negara Pancasila", "Meniru seluruh konstitusi negara barat"], 0, "Amandemen memperkokoh demokrasi, membatasi masa jabatan presiden, dan menegakkan supremasi HAM.");
addQ("pan-k6-u24", 6, "Analisis Ketetapan MPR yang Tidak Boleh Diubah", "sulit", "Dalam kesepakatan dasar amandemen UUD 1945, terdapat pasal yang disepakati secara mutlak untuk TIDAK BOLEH DIUBAH sama sekali, yaitu mengenai ...", ["Bentuk Negara Kesatuan Republik Indonesia (NKRI) dan Pembukaan UUD 1945", "Jumlah menteri dalam kabinet", "Batas usia menteri dan gubernur", "Jumlah anggota dewan perwakilan rakyat"], 0, "Bentuk NKRI dan Pembukaan UUD 1945 adalah komitmen final kebangsaan yang tidak dapat diubah.");
addQ("pan-k6-u25", 6, "Analisis Perlindungan Konservasi Cagar Biosfer Nusantara", "sulit", "Taman Nasional Komodo di NTT dan Taman Nasional Lorentz di Papua ditetapkan sebagai situs warisan dunia UNESCO. Kewajiban pemerintah dan seluruh warga negara terhadap kawasan konservasi ini adalah ...", ["Menjaga kelestarian habitat alami satwa endemik dari kerusakan eksploitasi komersial berlebihan", "Mengubah seluruh hutan lindung menjadi kawasan tambang emas", "Menangkap semua komodo untuk dijadikan hewan sirkus", "Menjual pulau pulau kecil ke pihak swasta asing"], 0, "Kawasan konservasi adalah amanah ekologis perlindungan biodiversitas bumi pertiwi.");
addQ("pan-k6-u26", 6, "Analisis Sumpah Pemuda Sebagai Modal Sosial Pembangunan", "sulit", "Ikrar 'Satu Nusa, Satu Bangsa, dan Satu Bahasa Indonesia' terbukti ampuh mencegah Indonesia terpecah belah seperti bangsa-bangsa di semenanjung Balkan. Nilai strategis modal sosial ini adalah ...", ["Membentuk identitas bersama yang melampaui sekat etnisitas dan primordialisme sempit", "Menghapuskan keberadaan suku dan budaya lokal", "Mewajibkan semua orang tinggal di satu pulau yang sama", "Melarang pernikahan antarsuku bangsa"], 0, "Kesadaran satu bangsa menjadi lem perekat kokoh yang mengintegrasikan ratusan suku bangsa.");
addQ("pan-k6-u27", 6, "Analisis Sikap Terhadap Kemiskinan dan Ketimpangan Sosial", "sulit", "Sila kelima Pancasila mengamanatkan keadilan sosial bagi seluruh rakyat Indonesia. Tindakan filantropi (kedermawanan sosial) seperti sedekah, zakat, donor darah, dan pendirian sekolah gratis merupakan wujud nyata ...", ["Solidaritas kemanusiaan dan redistribusi sosial membantu meringankan beban sesama warga negara", "Pamer status kekayaan di hadapan umum", "Tindakan mencampuri urusan kemiskinan orang lain", "Upaya menghindari razia petugas dinas sosial"], 0, "Kedermawanan sosial mempersempit jurang kesenjangan dan memperkuat solidaritas kebangsaan.");
addQ("pan-k6-u28", 6, "Analisis Keteladanan Sultan Hamengkubuwono IX", "sulit", "Setelah Proklamasi 17 Agustus 1945, Sri Sultan Hamengkubuwono IX dan Paku Alam VIII menyatakan Kraton Yogyakarta bergabung dengan Republik Indonesia dan menyediakan Yogyakarta sebagai ibu kota darurat serta membiayai pemerintahan RI. Sikap kepahlawanan Sultan Hamengkubuwono IX menunjukkan ...", ["Rela berkorban menyerahkan kedaulatan monarki keraton demi kejayaan Negara Kesatuan Republik Indonesia", "Keinginan menguasai seluruh pulau Jawa", "Ketakutan pada tentara Jepang", "Mencari jabatan menteri luar negeri"], 0, "Komitmen kepahlawanan Sultan HB IX adalah teladan pengorbanan tanpa pamrih demi NKRI.");
addQ("pan-k6-u29", 6, "Analisis Penanganan Pelanggaran HAM Berat", "sulit", "Pelanggaran HAM berat (seperti genosida dan kejahatan terhadap kemanusiaan) tidak mengenal daluwarsa dan diadili di Pengadilan HAM. Hal ini menegaskan komitmen konstitusi negara bahwa ...", ["Harkat, martabat, dan hak hidup setiap manusia dilindungi secara mutlak dan tidak boleh diinjak-injak oleh kekuasaan apa pun", "Hukum hanya membela pelaku kejahatan bersenjata", "Negara boleh melakukan apa saja kepada warga", "Keadilan hukum hanya berlaku bagi orang merdeka"], 0, "Penegakan hukum atas pelanggaran HAM menjamin keadilan bagi para korban dan supremasi nilai perikemanusiaan.");
addQ("pan-k6-u30", 6, "Komitmen Menjaga Pancasila Sebagai Benteng Masa Depan Bangsa", "sulit", "Di tengah persaingan peradaban global abad ke-21 yang sarat ideologi asing (seperti kapitalisme ekstrem, sekularisme radikal, dan ekstremisme), benteng paling kokoh yang menjamin eksistensi bangsa Indonesia tetap berdiri tegak adalah ...", ["Menjadikan Pancasila sebagai pedoman hidup, ideologi pemersatu, dan kompas moral dalam setiap kebijakan serta tindakan", "Membeli perlengkapan senjata perang nuklir sebanyak-banyaknya", "Mengisolasi diri dan memutuskan hubungan perdagangan dengan seluruh dunia", "Menghapus kurikulum pendidikan moral dan agama di sekolah"], 0, "Pancasila adalah falsafah abadi dan panduan etis bangsa Indonesia mengarungi samudera masa depan.");

